        return date.isBefore(policyDate(claim.sheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The claim's rate figure at the rate (a percent): its amount times the rate, rounded by {@link #rounding}, not yet floored; null (no rate) stays null. */
    public BigDecimal live(Claim claim, BigDecimal rate) {
        return rate == null ? null : claim.amount().multiply(rate).movePointLeft(2).setScale(2, rounding(claim));
    }

    /**
     * A claim's live due from its rate figure (or the figure a statement bound): the figure with its late charge added on top, then raised
     * to the floor in force on the claim's date ({@link #floored}). An open (OPEN or PENDING) claim whose due-by (fixed when it was made) plus
     * its grade's grace ({@link #overdueFrom}) is before {@code today} gains, for every full 30 days it is overdue, the late percent in force on
     * that boundary date (the due-by plus the grace plus 30, 60, 90 ... days)
     * of the figure plus the charges of the boundaries before it (compounding), each charge rounded by {@link #rounding}, the charges added up; a boundary whose percent is 0.00 adds nothing.
     * The charge is never bound by a statement, so it follows the sheet's today; null (no figure) stays null.
     * A correction has no late charge and no floor, and a deferred claim no late charge (it is not overdue until the sheet's today reaches its date).
     * A waived claim has no late charge, whatever its overdue state.
     */
    public BigDecimal withLate(Claim claim, BigDecimal figure, LocalDate today) {
        return floored(claim, lateAdded(claim, figure, today));
    }

    /** The figure with the claim's late charge on {@code today} added on top (see {@link #withLate}), not floored. */
    private BigDecimal lateAdded(Claim claim, BigDecimal figure, LocalDate today) {
        if (figure == null || !claim.status().isOpen() || claim.isCorrection() || claim.deferredOn(today) || claim.waived()) {
            return figure;
        }
        LocalDate dueBy = overdueFrom(claim);
        if (!dueBy.isBefore(today)) {
            return figure;
        }
        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
        RoundingMode rounding = rounding(claim);
        BigDecimal total = figure;
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = latePct(claim.sheetId(), dueBy.plusDays(30 * n));
            if (pct.signum() != 0) {
                total = total.add(total.multiply(pct).movePointLeft(2).setScale(2, rounding));
            }
        }
        return total;
    }

    /** The claim's due (its figure plus its late charge) raised to the floor in force on the claim's date; null (no due) stays null, and a correction's due has no floor. */
    public BigDecimal floored(Claim claim, BigDecimal due) {
        return due == null || claim.isCorrection() ? due : due.max(floor(claim.sheetId(), claim.date()));
    }

    /** The key an action's permitted roles are kept under: perm-<action>. */
    public static String permKey(String action) {
        return "perm-" + action;
    }

    /** The roles an action is permitted to, as saved: a comma separated list, or "" for the standing rule. */
    public String perm(String sheetId, String action) {
        return get(sheetId, permKey(action));
    }

    /** The standing rule: reassign and reopen by steward; open, settle, void and close by clerk and steward. */
    private static List<String> standing(String action) {
        return action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD) : ROLES;
    }

    /** Whether the user's role may take the action on the sheet: as the permission matrix has it, else by the standing rule. */
    public boolean permits(String sheetId, String action, String user) {
        String saved = perm(sheetId, action);
        List<String> roles = saved.isEmpty() ? standing(action) : List.of(saved.split(","));
        return roles.contains(role(sheetId, user));
    }

    /** The sheet's roles, by user name. */
    public List<Role> roles(String sheetId) {
        return jdbc.query("SELECT * FROM " + AsOf.table("sheet_role") + " WHERE sheet_id = ? ORDER BY user_name",
                (rs, n) -> new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role")), sheetId);
    }

    /** The role the user acts in: steward while the sheet's today is inside a delegation to them, else the role the sheet gave them. */
    public String role(String sheetId, String user) {
        return delegator(sheetId, user) != null ? STEWARD : givenRole(sheetId, user);
    }

    /** The steward who delegated the steward role to the user for the sheet's today; null when none did. */
    public String delegator(String sheetId, String user) {
        return delegator(sheetId, user, sheets.today(sheetId));
    }

    /** The steward who delegated the steward role to the user for {@code on}; null when none did. */
    public String delegator(String sheetId, String user, java.time.LocalDate on) {
        String name = user == null ? "" : user.trim();
        return name.isEmpty() ? null : delegations.delegator(sheetId, name, on);
    }

    /** The role the sheet gave the user: clerk unless it gave them another (a delegation aside). */
    public String givenRole(String sheetId, String user) {
                throw new ClaimStatusRefusedException("A SETTLED claim can be voided only within "
                        + ClaimStatus.VOID_SETTLED_DAYS + " days of its settlement.");
            }
        }
        if (claim.status() == ClaimStatus.PENDING && (next == ClaimStatus.SETTLED || next == ClaimStatus.OPEN)
                && !steward) {
            throw new ClaimStatusRefusedException("Only a steward can approve or reject a pending claim.");
        }
        if (claim.status() == ClaimStatus.PENDING && next == ClaimStatus.OPEN && reason.isEmpty()) {
            throw new ClaimStatusRefusedException("Give a reason to reject the claim.");
        }
        // While the sheet has void reasons, a claim is voided only with one of them; with none, no reason is kept.
        if (next == ClaimStatus.VOID) {
            List<String> reasons = voidReasons.list(claim.sheetId());
            if (reasons.isEmpty()) {
                voidReason = "";
            } else if (!reasons.contains(voidReason)) {
                throw new ClaimVoidReasonNeededException(voidReason.isEmpty()
                        ? "Choose a void reason to void the claim."
                        : "\"" + voidReason + "\" is not one of the sheet's void reasons.");
            }
        }
        // Settling (or approving) freezes the late charge on the sheet's today into the due.
        BigDecimal due = settings.withLate(claim, due(claim, people, rates, settings), sheets.today(claim.sheetId()));
        // A claim whose due is above the proof threshold in force on its date (its person's grade's, else the sheet's) is settled or approved only once it has a
        // proof, whoever settles it, and before the clerk limit is considered (a due of n/a is within any threshold).
        if (next == ClaimStatus.SETTLED && claim.proofs() == 0 && due != null) {
            BigDecimal threshold = settings.proofThreshold(claim);
            if (threshold != null && due.compareTo(threshold) > 0) {
                throw new ClaimProofNeededException("The claim's due is above the proof threshold (" + threshold.toPlainString()
                        + "): add a proof before it is " + (claim.status() == ClaimStatus.PENDING ? "approved." : "settled."));
            }
        }
        // A claim whose due is above the note threshold in force on its date is opened only once it has a note (a due
        // of n/a is within any threshold).
        if (next == ClaimStatus.OPEN && claim.status() == ClaimStatus.DRAFT && due != null
                && (claim.note() == null || claim.note().isBlank())) {
            BigDecimal threshold = settings.noteThreshold(claim.sheetId(), claim.date());
            if (threshold != null && due.compareTo(threshold) > 0) {
                throw new ClaimNoteNeededException("The claim's due is above the note threshold (" + threshold.toPlainString()
                        + "): give it a note before it is opened.");
            }
        }
        // A clerk settles only a claim whose due is at or below the clerk limit (a due of n/a is within any
        // limit); above it the claim goes PENDING, for a steward to approve. A steward settles anything.
        if (next == ClaimStatus.SETTLED && claim.status() == ClaimStatus.OPEN && due != null && !steward) {
            BigDecimal limit = settings.clerkLimit(claim.sheetId());
            if (limit != null && due.compareTo(limit) > 0) {
                next = ClaimStatus.PENDING;
            }
        }
        // A DRAFT claim belonging to a period that caps its claims (its due-by falls in it) is opened only while its
        // person has fewer OPEN or PENDING claims in the period than the cap.
        if (next == ClaimStatus.OPEN && claim.status() == ClaimStatus.DRAFT) {
            Period capped = periods.on(claim.sheetId(), claim.dueBy());
            if (capped != null && capped.cap() != null
                    && claims.openInPeriod(claim.sheetId(), claim.personId(), capped) >= capped.cap()) {
                throw new ClaimStatusRefusedException("The person already has " + capped.cap()
                        + " open or pending claims in the period " + capped.name() + ", its cap.");
            }
        }
        // A DRAFT claim whose due is above the review threshold in force on its date goes to REVIEW instead of OPEN
        // (a due of n/a is within any threshold): it is numbered only when a steward's review makes it OPEN.
        if (next == ClaimStatus.OPEN && claim.status() == ClaimStatus.DRAFT && due != null) {
            BigDecimal threshold = settings.reviewThreshold(claim.sheetId(), claim.date());
            if (threshold != null && due.compareTo(threshold) > 0) {
                next = ClaimStatus.REVIEW;
            }
        }
        // While the sheet numbers by period (its today on or after the from-date), an opened claim is numbered
        // within the period its due-by falls in, or in the no-period sequence; otherwise sheet-wide.
        String scope = null;
        LocalDate numberingFrom = settings.periodNumberingFrom(claim.sheetId());
        if (next == ClaimStatus.OPEN && numberingFrom != null && !sheets.today(claim.sheetId()).isBefore(numberingFrom)) {
            Period period = periods.on(claim.sheetId(), claim.dueBy());
            scope = period == null ? "" : period.name();
        }
        Claim changed = claims.changeStatus(claim, next, due, user, scope);
        if (changed == null) {
            throw new ClaimStatusRefusedException("A " + claim.status() + " claim cannot become " + next + ".");
        }
        // Settled one at a time, the claim leaves any batch that settled it before (a bulk settle records its batch after).
        if (!decision && (next == ClaimStatus.SETTLED || next == ClaimStatus.PENDING)) {
            batches.remove(changed.id());
        }
        if (next == ClaimStatus.VOID && !voidReason.isEmpty()) {
            voidReasons.voided(changed.id(), voidReason);
        }
        claims.log(changed, user, sheets.today(claim.sheetId()), rollup.figure(changed));
        responseOut.set(ClaimResponse.from(changed));
        requestOut.set(new ClaimStatusRequest(action, reason, voidReason));
    }

    /**
     * The claim's due now, before its late charge: the figure its person's last statement bound it to (a PENDING
     * claim too), otherwise its amount times its
     * person's grade's rate on the claim's date, rounded by the policy date (not yet floored); null when none applies.
     */
    private static BigDecimal due(Claim claim, People people, Rates rates, Settings settings) {
        if (claim.stated()) {
            return claim.statedDue();
        }
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person == null) {
            return null;
        }
        BigDecimal rate = rates.forClaim(claim, person.gradeOn(claim.date()));
        return settings.live(claim, rate);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;

public class ApplyResettle {
    // Only a steward re-settles, and only a SETTLED claim. The new figure is the one the claim would have today as an
    // open claim bound by no statement: its amount times its person's grade's rate on its date (as they stand now),
    // rounded by the policy date, with the late charge on the sheet's today added on top, then raised to the floor.
    public void apply(@Val Claim claim, Claims claims, People people, Rates rates, Settings settings, Sheets sheets,
            ServerHttpConnection connection, Out<ClaimResponse> responseOut, Out<Resettled> resettledOut)
            throws ClaimResettleRefusedException {
        String user = Audit.user(connection).trim();
        if (!Settings.STEWARD.equals(settings.role(claim.sheetId(), user))) {
            throw new ClaimResettleRefusedException("Only a steward can re-settle a claim.");
        }
        if (claim.status() != ClaimStatus.SETTLED) {
            throw new ClaimResettleRefusedException("Only a SETTLED claim can be re-settled.");
        }
        BigDecimal due = null;
        Person person = people.find(claim.sheetId(), claim.personId());
        if (person != null) {
            BigDecimal rate = rates.forClaim(claim, person.gradeOn(claim.date()));
            Claim open = claim.withStatus(ClaimStatus.OPEN, claim.number(), null, claim.openedBy());
            due = settings.withLate(open, settings.live(claim, rate), sheets.today(claim.sheetId()));
        }
        Claim changed = claims.resettle(claim, due);
        if (changed == null) {
            throw new ClaimResettleRefusedException("Only a SETTLED claim can be re-settled.");
        }
        claims.log(changed, user, sheets.today(claim.sheetId()), due);
        responseOut.set(ClaimResponse.from(changed));
        resettledOut.set(new Resettled(claim.settledDue(), due));
    }
}

