  if (!person) return 'n/a';
  const rate = rateFor(rates, gradeOn(person, today), today);
  const figures = claims
    .filter((c) => c.personId === person.id && counts(c, people, today))
    .map((c) => figure(c, rates, person, floor, late))
    .filter((d) => d !== 'n/a');
